import neostandard, { resolveIgnoresFromGitignore } from 'neostandard'

export default [
  // A standalone `ignores` entry is a global ignore in ESLint's flat config.
  // neostandard 0.14 scopes its own `ignores` option to its file-matched
  // configs, which no longer keeps these out of the lint run.
  {
    ignores: [
      ...resolveIgnoresFromGitignore(),
      // e2e fixtures mirroring upstream's layout (step discovery inside a
      // dot-prefixed directory); not written to this repo's style.
      'e2e-v5/app/.well-known/',
      'e2e-v4/app/.well-known/',
      // Auto-generated by `next build` — Next owns the formatting.
      'e2e-v5/next-env.d.ts',
      'e2e-v4/next-env.d.ts',
      'packages/world/dist/',
      'packages/workflow/dist/',
      'packages/workflow-fastify/dist/',
      'examples/*/.well-known/',
    ],
  },
  ...neostandard({ ts: true }),
]
